import { confirm } from "@inquirer/prompts";

export async function confirmOverwrite(message: string): Promise<boolean> {
  return confirm({ message, default: false });
}

export async function confirmInstallMode(message: string): Promise<"copy" | "plugin"> {
  const asPlugin = await confirm({
    message: message || "Register as a plugin (always fresh) instead of copying files? Choose No to copy editable files.",
    default: false,
  });
  return asPlugin ? "plugin" : "copy";
}

# Inputs

| Placeholder | Required | Description | Default |
|---|---|---|---|
| `CLI NAME` → "opencode-myextension" | Yes | CLI command name; matches package.json bin field | — |
| `VERSION` → "1.0.0" | Yes | Initial version | `1.0.0` |
| `COMMANDS` | Yes | install / uninstall / status / migrate / clear-cache subcommands | — |
| `SCOPE` → "local" | Yes | Default scope when `--scope` is not specified | `local` |

The module exports `runCli(argv)` and runs standalone under its shebang via the `import.meta.main` guard — both `bunx <package>` (through the package.json `bin` entry) and the `index.ts` dispatch shim resolve to the same `runCli`.

**Load-bearing — do not simplify:** this file is an adapter rendering (ADR-0013): argument parsing, help, and output formatting live here; the machinery comes from `./installer.ts` (this package's policy adapter) and the `opencode-architect/core` dependency (status types and the effective-version pipeline). The deployment plan is content-based, so `install` resolves the mode through `resolveMode` and never forces one: assets-only packages default to copy and accept `--mode plugin`; code-backed packages always register and `--mode copy` surfaces the `CopyModeUnsupportedError` as a hard, explanatory exit-1 error; `install` forwards `force` so consumer-modified files are skipped without it; `status` delegates to the core status pipeline (registration, target config file, raw entry as written, resolved source on disk with a relative-age staleness hint, the published npm latest per scope, and an effective verdict that annotates a double-scope registration) — the status-only `--online` (registry staleness, warn-and-continue) and `--path` flags are rejected with an explanatory exit-1 on every other command; `migrate` refuses to run without `--force` (root-config deletion is consent-gated and CLI-only); `clear-cache` is self-only — it removes this package's own cache copies (`<package>` and every `<package>@*`) from OpenCode's package cache, is idempotent (nothing cached is a success), warns and continues on per-target removal failures, and must never grow `--package` or `--all` modes (other packages' cache and the shared OpenCode cache dir are out of scope for a generated package); the module lives at `src/cli.ts` and imports `./installer.ts`.

---
#!/usr/bin/env bun
import type { Stats } from "node:fs";
import { stat } from "node:fs/promises";
import { resolve } from "node:path";
import { parseArgs } from "node:util";
import { install, uninstall, status, migrateRootConfig, clearPackageCache, CopyModeUnsupportedError, type Scope, type InstallMode } from "./installer.ts";
import { StatusReporter, type EffectiveVersion, type ResolvedSource } from "opencode-architect/core";

const VERSION = JSON.parse(
  await Bun.file(`${import.meta.dirname}/../package.json`).text()
).version;

function printHelp(): void {
  console.log(`
opencode-myextension v${VERSION}

Commands:
  install     Install myextension (copy by default; plugin registration with --mode plugin)
  uninstall   Remove myextension (payload files and/or plugin registration, per manifest)
  status      Resolve what a session would load: registration, config file, raw entry,
              the resolved source on disk, and an effective verdict per scope
  migrate     Migrate root opencode.json into .opencode/ (asks for --force consent)
  clear-cache Remove cached copies of this package from OpenCode's package cache

Options:
  -s, --scope <scope>    Installation scope: "local" or "global" (default: local)
  -m, --mode <mode>      Install mode: "copy" (default for assets-only) or "plugin" (mandatory for code-backed)
  -f, --force           Overwrite consumer-modified files / consent to migration
      --online          status: also query the npm registry for the latest published
                        version and flag staleness; network failures warn and continue
      --path <dir>      status: resolve against another project directory instead of
                        the current working directory; the directory must exist
  -h, --help            Show this help message
  -v, --version         Show version

Examples:
  opencode-myextension install
  opencode-myextension install --scope global
  opencode-myextension install --mode plugin
  opencode-myextension uninstall --scope local
  opencode-myextension status
  opencode-myextension status --online
  opencode-myextension status --path ../other-project
  opencode-myextension migrate --force
  opencode-myextension clear-cache
`);
}

function isInstallMode(value: string): value is InstallMode {
  return value === "copy" || value === "plugin";
}

export async function runCli(argv: string[]): Promise<number> {
  const { positionals, values } = parseArgs({
    args: argv,
    options: {
      scope: { type: "string", short: "s" },
      mode: { type: "string", short: "m" },
      force: { type: "boolean", short: "f", default: false },
      online: { type: "boolean", default: false },
      path: { type: "string" },
      help: { type: "boolean", short: "h", default: false },
      version: { type: "boolean", short: "v", default: false },
    },
    allowPositionals: true,
    strict: true,
  });

  if (values.version) { console.log(`opencode-myextension v${VERSION}`); return 0; }
  if (values.help || positionals.length === 0) { printHelp(); return 0; }

  const command = positionals[0];
  if (command !== "status" && (values.path !== undefined || values.online)) {
    console.error("--path and --online only apply to the status command.");
    return 1;
  }
  const scope: Scope | undefined = values.scope as Scope | undefined;
  const mode: InstallMode | undefined =
    values.mode === undefined ? undefined : isInstallMode(values.mode) ? values.mode : ("invalid" as InstallMode);
  const force: boolean = values.force;
  const online: boolean = values.online;

  if (scope && scope !== "local" && scope !== "global") {
    console.error(`Invalid scope: ${scope}. Must be "local" or "global".`);
    return 1;
  }
  if (mode === ("invalid" as InstallMode)) {
    console.error(`Invalid mode: ${values.mode}. Must be "copy" or "plugin".`);
    return 1;
  }

  try {
    switch (command) {
      case "install": {
        const installScope = scope || "local";
        const result = await install(installScope, process.cwd(), { mode, force });
        console.log(`Installed ${installScope} (mode: ${result.mode})${result.upToDate ? " (already up to date)" : ""}:`);
        if (result.mode === "copy") {
          console.log(`  Skill: ${result.skillPath}`);
          console.log(`  Command: ${result.commandPath}`);
          for (const skipped of result.skippedModified) {
            console.log(`  Skipped consumer-modified: ${skipped} (use --force to overwrite)`);
          }
        } else {
          console.log(`  Plugin entry: ${result.entry} in ${result.entryConfigPath}`);
        }
        for (const cleared of result.clearedCache) {
          console.log(`  Cleared cache: ${cleared}`);
        }
        break;
      }
      case "uninstall": {
        const uninstallScope = scope || "local";
        const result = await uninstall(uninstallScope, process.cwd());
        console.log(`Uninstalled ${uninstallScope}${result.mode ? ` (mode: ${result.mode})` : ""}:`);
        if (result.removed.length > 0) console.log(`  Removed: ${result.removed.join(", ")}`);
        if (result.pluginRemoved) console.log(`  Removed plugin registration`);
        break;
      }
      case "status": {
        const projectDir = await resolveProjectDir(values.path);
        const report = await status(projectDir, online);
        console.log("Status:");
        for (const [label, scopeReport] of [["Local", report.scopes[0]], ["Global", report.scopes[1]]] as const) {
          if (!scopeReport) continue;
          if (!scopeReport.registered && scopeReport.manifestVersion === null) continue;
          const npm = scopeReport.publishedVersion !== null ? ` npm-latest=${scopeReport.publishedVersion}` : "";
          console.log(
            `  ${label}: mode=${scopeReport.mode === "none" ? "unknown" : scopeReport.mode}, ` +
                `config=${scopeReport.configPath ?? "-"}, ` +
                `entry=${scopeReport.entryText ?? "-"}, ` +
                `resolved=${resolvedLabel(scopeReport.resolved)}${npm}`
          );
          for (const warning of scopeReport.warnings) console.warn(`Warning: ${warning}`);
        }
        if (report.effective.scope !== null) {
          console.log(`  should load: ${verdictLabel(report.effective)}`);
        } else {
          console.log("  should load: nothing (not registered in any scope)");
        }
        for (const warning of report.warnings) console.warn(`Warning: ${warning}`);
        break;
      }
      case "migrate": {
        if (!force) {
          console.error("Migration deletes the root opencode.json. Re-run with --force to consent.");
          return 1;
        }
        const migrated = await migrateRootConfig(process.cwd(), async () => true);
        console.log(migrated ? "Migrated opencode.json into .opencode/opencode.json" : "Nothing to migrate");
        break;
      }
      case "clear-cache": {
        if (positionals.length > 1) {
          console.error(`Unexpected arguments for clear-cache: ${positionals.slice(1).join(" ")}`);
          return 1;
        }
        const outcome = await clearPackageCache();
        if (outcome.removed.length === 0) {
          console.log("No cached copies found; nothing to remove.");
        } else {
          console.log("Removed cached copies:");
          for (const target of outcome.removed) console.log(`  Removed: ${target}`);
        }
        for (const warning of outcome.warnings) {
          console.warn(`  Warning: ${warning}`);
        }
        break;
      }
      default: console.error(`Unknown command: ${command}`); printHelp(); return 1;
    }
    return 0;
  } catch (error) {
    if (error instanceof CopyModeUnsupportedError) {
      console.error(`Error: ${error.message}`);
      return 1;
    }
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Error: ${message}`);
    return 1;
  }
}

async function resolveProjectDir(input: string | undefined): Promise<string> {
  if (input === undefined) return process.cwd();
  const cleaned = stripQuotes(input.trim());
  const resolved = resolve(cleaned);
  let info: Stats | null = null;
  try {
    info = await stat(resolved);
  } catch {
    throw new Error(`--path does not exist: ${input}`);
  }
  if (!info.isDirectory()) throw new Error(`--path is not a directory: ${input}`);
  return resolved;
}

function stripQuotes(value: string): string {
  if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) return value.slice(1, -1);
  if (value.length >= 2 && value.startsWith("'") && value.endsWith("'")) return value.slice(1, -1);
  return value;
}

function resolvedLabel(source: ResolvedSource | null): string {
  if (source === null) return "-";
  const age = StatusReporter.formatAge(source.modifiedMs);
  const sourceLabel = source.source === "cache" ? "cache copy" : "checkout copy";
  return `${source.version ?? "unknown"} (${age === null ? sourceLabel : `${sourceLabel}, ${age}`})`;
}

function verdictLabel(effective: EffectiveVersion): string {
  const latest =
    effective.latestVersion !== null && effective.versionKind !== "npm" ? `, latest ${effective.latestVersion}` : "";
  const scopeLabel =
    effective.registeredScopes.length > 1
      ? `${effective.registeredScopes.join(" + ")}; both scopes register — double-load`
      : effective.scope;
  return `${effective.version ?? "unknown"} (${kindLabel(effective.versionKind)}, ${scopeLabel}${latest})`;
}

function kindLabel(kind: EffectiveVersion["versionKind"]): string {
  if (kind === "cache") return "cache copy";
  if (kind === "checkout") return "checkout copy";
  if (kind === "spec") return "pinned spec";
  if (kind === "npm") return "npm latest";
  if (kind === "manifest") return "manifest";
  return "unresolved";
}

if (import.meta.main) {
  process.exitCode = await runCli(process.argv.slice(2));
}

# Inputs

| Placeholder | Required | Description | Default |
|---|---|---|---|
| `EXTENSION NAME` → "myextension" | Yes | Extension identifier (e.g., "mytool") | - |
| `SKILL NAME` → "myextension" | Yes | Must match the folder name in skills/ at the package root | - |
| `COMMAND NAME` → "my-command.md" | Yes | Command file name in commands/ at the package root | - |
| `PACKAGE NAME` → "opencode-myextension" | Yes | npm package name; also the manifest file base | - |

**Load-bearing — do not simplify:** this file is an adapter rendering
(ADR-0013): the machinery it orchestrates comes from the
`opencode-architect/core` dependency — manifest io with per-file sha256
hashes (`InstallManifest`), the surgical config editor (`PluginConfigEditor`),
scope bases (`scopeBase`), package-cache paths and cache-target removal
(`NpmCache`, `removeCacheTargets`), and the status/effective-version pipeline
(`StatusReporter`). The adapter declares this package's policy as the
constants below (`PLUGIN_NAME`, `SKILL_NAME`, `COMMAND_NAME`,
`ASSET_LAYOUT_DIR`) and must not re-implement machinery. The deployment plan
is content-based (ADR-0008): `"content": "code"` packages always
plugin-register and `--mode copy` throws `CopyModeUnsupportedError`;
assets-only packages copy-install by default with `--mode plugin` as opt-in;
copy install touches no config file. Idempotency is the core manifest
(ADR-0006): a matching version, a present registration, and hash-matching
payload files are a zero-write no-op; consumer-modified files are skipped
with a warning unless `force`, and are recorded with their packaged hash so
`--force` can take ownership; a missing or empty asset source is a hard error
naming the path, and a manifest is never written when zero files were
written. Cache hygiene is self-scoped (ADR-0007): installs — including
no-ops — prune only this package's cache copies through the core
`removeCacheTargets`; the load hook never prunes. `status()` delegates to the
core `StatusReporter` with a manifest lookup bound to this package, is
read-only, and only touches the npm registry when `online` (warn-and-continue
on an injectable failure). `migrateRootConfig` deletes nothing without a
consent callback and is never called from `ensureAssets`. Every function is
scope-parameterized: local and global differ only in the base path
(`scopeBase`), never in behavior.

---
import { exists, mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { join, relative } from "node:path";
import {
  InstallManifest,
  NpmCache,
  PluginConfigEditor,
  StatusReporter,
  removeCacheTargets,
  scopeBase,
  sha256,
  listFilesRecursive,
  type ManifestData,
  type StatusReport,
  type Scope,
} from "opencode-architect/core";

export type { StatusReport, Scope };

export type InstallMode = "copy" | "plugin";

export interface InstallOptions {
  mode?: InstallMode;
  force?: boolean;
}

export interface InstallResult {
  scope: Scope;
  mode: InstallMode;
  skillPath: string;
  commandPath: string;
  entry: string | null;
  entryConfigPath: string | null;
  skippedModified: string[];
  upToDate: boolean;
  clearedCache: string[];
}

export interface UninstallResult {
  scope: Scope;
  mode: InstallMode | null;
  removed: string[];
  pluginRemoved: boolean;
}

// --- policy: this package's declared seam constants (ADR-0013) ---
const SKILL_NAME = "myextension";
const COMMAND_NAME = "my-command.md";
const PLUGIN_NAME = "opencode-myextension";
const ASSET_LAYOUT_DIR = ".";

const editor = new PluginConfigEditor();
const cache = new NpmCache();

export class CopyModeUnsupportedError extends Error {
  constructor() {
    super(
      `${PLUGIN_NAME} is code-backed (agents, tools, or plugin integrations) and cannot be installed in copy mode. ` +
        `Code-backed packages register as a plugin: run without --mode, or with --mode plugin.`
    );
  }
}

class AssetSourceMissingError extends Error {
  constructor(missingPath: string, cacheDir: string) {
    super(
      `Bundled asset directory missing or empty: ${missingPath}. ` +
        `The ${PLUGIN_NAME} package cache at ${cacheDir} is partial. ` +
        `Clear that directory and reinstall with: bunx ${PLUGIN_NAME} install --scope global`
    );
  }
}

export async function getPackageVersion(): Promise<string> {
  const content = await Bun.file(`${import.meta.dirname}/../package.json`).text();
  return JSON.parse(content).version;
}

export async function getPackageName(): Promise<string> {
  const content = await Bun.file(`${import.meta.dirname}/../package.json`).text();
  return JSON.parse(content).name;
}

export async function getContentDeclaration(): Promise<"assets" | "code"> {
  const content = await Bun.file(`${import.meta.dirname}/../package.json`).text();
  return JSON.parse(content).content === "code" ? "code" : "assets";
}

export async function resolveMode(requested: InstallMode | undefined): Promise<InstallMode> {
  if ((await getContentDeclaration()) === "code") {
    if (requested === "copy") throw new CopyModeUnsupportedError();
    return "plugin";
  }
  return requested ?? "copy";
}

function getPackageDir(): string {
  return join(import.meta.dirname, "..");
}

export function packageCacheRoot(): string {
  return cache.root();
}

export async function prunePackageCache(): Promise<{ removed: string[]; warnings: string[] }> {
  const version = await getPackageVersion();
  const wanted = [PLUGIN_NAME, `${PLUGIN_NAME}@latest`, `${PLUGIN_NAME}@${version}`];
  return removeCacheTargets(cache.root(), (name) => wanted.includes(name));
}

export async function clearPackageCache(): Promise<{ removed: string[]; warnings: string[] }> {
  const prefix = `${PLUGIN_NAME}@`;
  return removeCacheTargets(cache.root(), (name) => name === PLUGIN_NAME || name.startsWith(prefix));
}

async function copyDir(src: string, dest: string, skip: Set<string> = new Set()): Promise<number> {
  await mkdir(dest, { recursive: true });
  if (skip.has(dest)) return 0;
  let written = 0;
  for (const entry of await readdir(src, { withFileTypes: true })) {
    const s = join(src, entry.name);
    const d = join(dest, entry.name);
    if (skip.has(d)) continue;
    if (entry.isDirectory()) {
      written += await copyDir(s, d, skip);
    } else {
      await Bun.write(d, Bun.file(s));
      written++;
    }
  }
  return written;
}

async function requireAssetDir(path: string): Promise<string> {
  if (!(await exists(path))) throw new AssetSourceMissingError(path, getPackageDir());
  const contents = await readdir(path);
  if (contents.length === 0) throw new AssetSourceMissingError(path, getPackageDir());
  return path;
}

async function payloadPaths(configBase: string): Promise<{ skillPath: string; commandPath: string }> {
  return {
    skillPath: join(configBase, "skills", SKILL_NAME),
    commandPath: join(configBase, "commands", COMMAND_NAME),
  };
}

async function ensurePayload(scope: Scope, projectDir: string, force: boolean): Promise<{ upToDate: boolean; skippedModified: string[] }> {
  const version = await getPackageVersion();
  const configBase = scopeBase(scope, projectDir);
  const { skillPath } = await payloadPaths(configBase);
  const manifest = new InstallManifest(configBase, PLUGIN_NAME);
  const existing = await manifest.read();
  const payloadRecorded = existing !== null && Object.keys(existing.files).length > 0;
  if (payloadRecorded && (await manifest.isUpToDate(version, configBase))) {
    return { upToDate: true, skippedModified: [] };
  }
  const skippedModified: string[] = [];
  const modified = await manifest.findConsumerModified(configBase);
  if (!force && modified.length > 0) {
    for (const file of modified) {
      console.warn(`Warning: skipping consumer-modified file ${file} (use --force to overwrite).`);
    }
    skippedModified.push(...modified);
  }
  const packagedSkillDir = await requireAssetDir(join(getPackageDir(), ASSET_LAYOUT_DIR, "skills", SKILL_NAME));
  const written = await copyDir(packagedSkillDir, skillPath, new Set(skippedModified));
  if (written === 0 && skippedModified.length === 0) throw new AssetSourceMissingError(packagedSkillDir, getPackageDir());
  const { commandPath } = await payloadPaths(configBase);
  const commandSource = await requireAssetDir(join(getPackageDir(), ASSET_LAYOUT_DIR, "commands"));
  await mkdir(join(configBase, "commands"), { recursive: true });
  await Bun.write(commandPath, Bun.file(join(commandSource, COMMAND_NAME)));
  const skipped = new Set(skippedModified);
  const hashes: Record<string, string> = {};
  for (const file of [...(await listFilesRecursive(skillPath)), commandPath]) {
    const rel = relative(configBase, file).replaceAll("\\", "/");
    const packagedCounterpart = file.startsWith(skillPath)
      ? join(packagedSkillDir, relative(skillPath, file))
      : join(commandSource, COMMAND_NAME);
    hashes[rel] = await sha256(skipped.has(file) ? packagedCounterpart : file);
  }
  await manifest.write({
    version,
    mode: existing?.mode ?? "copy",
    entry: existing?.entry ?? null,
    entryConfigPath: existing?.entryConfigPath ?? null,
    rootDir: null,
    files: null,
    hashes,
  });
  return { upToDate: false, skippedModified };
}

export async function ensureAssets(scope: Scope, projectDir: string, force: boolean): Promise<void> {
  await ensurePayload(scope, projectDir, force);
}

async function registerPlugin(scope: Scope, projectDir: string): Promise<{ upToDate: boolean; entry: string | null; entryConfigPath: string | null }> {
  const version = await getPackageVersion();
  const configBase = scopeBase(scope, projectDir);
  const entry = `${PLUGIN_NAME}@latest`;
  const manifest = new InstallManifest(configBase, PLUGIN_NAME);
  const existing = await manifest.read();
  const entryPresent = existing?.mode === "plugin" && existing.entryConfigPath
    ? (await editor.findRegistration(PLUGIN_NAME, { scope, projectDir })) !== null
    : false;
  if (existing?.version === version && entryPresent) {
    return { upToDate: true, entry: existing.entry, entryConfigPath: existing.entryConfigPath };
  }
  const outcome = await editor.ensurePluginEntry(PLUGIN_NAME, { scope, projectDir });
  if (outcome.action === "blocked" && outcome.warning) {
    console.warn(`Warning: ${outcome.warning}`);
    return { upToDate: false, entry: null, entryConfigPath: null };
  }
  if (outcome.action !== "noop" && outcome.action !== "updated" && outcome.action !== "created") {
    return { upToDate: false, entry: null, entryConfigPath: null };
  }
  await manifest.write({
    version,
    mode: "plugin",
    entry,
    entryConfigPath: outcome.configPath,
    rootDir: null,
    files: null,
    hashes: existing?.files ?? null,
  });
  return { upToDate: false, entry, entryConfigPath: outcome.configPath };
}

export async function checkMigrationNeeded(projectDir: string): Promise<{
  needed: boolean;
  rootConfigPath: string;
  dotOpenencodeConfigPath: string;
  rootConfig: Record<string, unknown> | null;
  dotOpenencodeConfig: Record<string, unknown> | null;
}> {
  const rootConfigPath = join(projectDir, "opencode.json");
  const dotOpenencodeConfigPath = join(projectDir, ".opencode", "opencode.json");
  const rootExists = await exists(rootConfigPath);
  const dotOpenencodeExists = await exists(dotOpenencodeConfigPath);
  if (!rootExists) return { needed: false, rootConfigPath, dotOpenencodeConfigPath, rootConfig: null, dotOpenencodeConfig: null };
  const rootConfig = await readJsonConfig(rootConfigPath);
  const dotOpenencodeConfig = dotOpenencodeExists ? await readJsonConfig(dotOpenencodeConfigPath) : null;
  return { needed: true, rootConfigPath, dotOpenencodeConfigPath, rootConfig, dotOpenencodeConfig };
}

export async function migrateRootConfig(
  projectDir: string,
  onConsent: (root: Record<string, unknown>, dot: Record<string, unknown> | null) => Promise<boolean>
): Promise<boolean> {
  const { needed, rootConfigPath, dotOpenencodeConfigPath, rootConfig, dotOpenencodeConfig } = await checkMigrationNeeded(projectDir);
  if (!needed || rootConfig === null) return false;
  if (!(await onConsent(rootConfig, dotOpenencodeConfig))) return false;
  if (dotOpenencodeConfig !== null) {
    const merged = { ...rootConfig, ...dotOpenencodeConfig };
    await writeJsonConfig(dotOpenencodeConfigPath, merged);
  } else {
    await mkdir(join(projectDir, ".opencode"), { recursive: true });
    await writeJsonConfig(dotOpenencodeConfigPath, rootConfig);
  }
  await rm(rootConfigPath);
  return true;
}

export async function install(
  scope: Scope,
  projectDir: string = process.cwd(),
  options: InstallOptions = {}
): Promise<InstallResult> {
  const { mode: requested, force = false } = options;
  const cacheOutcome = await prunePackageCache();
  for (const warning of cacheOutcome.warnings) {
    console.warn(`Warning: ${warning}`);
  }
  const mode = await resolveMode(requested);
  const configBase = scopeBase(scope, projectDir);
  const { skillPath, commandPath } = await payloadPaths(configBase);
  if (mode === "copy") {
    const { upToDate, skippedModified } = await ensurePayload(scope, projectDir, force);
    return { scope, mode, skillPath, commandPath, entry: null, entryConfigPath: null, skippedModified, upToDate, clearedCache: cacheOutcome.removed };
  }
  const { upToDate, entry, entryConfigPath } = await registerPlugin(scope, projectDir);
  return { scope, mode, skillPath, commandPath, entry, entryConfigPath, skippedModified: [], upToDate, clearedCache: cacheOutcome.removed };
}

export async function uninstall(scope: Scope, projectDir: string = process.cwd()): Promise<UninstallResult> {
  const configBase = scopeBase(scope, projectDir);
  const { skillPath, commandPath } = await payloadPaths(configBase);
  const manifest = new InstallManifest(configBase, PLUGIN_NAME);
  const manifestData = await manifest.read();
  const removed: string[] = [];
  let pluginRemoved = false;
  if (manifestData?.mode === "plugin") {
    const outcome = await editor.removePluginEntry(PLUGIN_NAME, { scope, projectDir });
    if (outcome.action === "blocked" && outcome.warning) console.warn(`Warning: ${outcome.warning}`);
    pluginRemoved = outcome.action === "removed";
  }
  if (await exists(skillPath)) { await rm(skillPath, { recursive: true }); removed.push(skillPath); }
  if (await exists(commandPath)) { await rm(commandPath); removed.push(commandPath); }
  if (manifestData !== null) { await rm(join(configBase, `${PLUGIN_NAME}.manifest.json`)); removed.push(join(configBase, `${PLUGIN_NAME}.manifest.json`)); }
  const skillsDir = join(configBase, "skills");
  const commandsDir = join(configBase, "commands");
  try { const skillsContents = await readdir(skillsDir); if (skillsContents.length === 0) await rm(skillsDir, { recursive: true }); } catch {}
  try { const commandsContents = await readdir(commandsDir); if (commandsContents.length === 0) await rm(commandsDir, { recursive: true }); } catch {}
  return { scope, mode: manifestData?.mode ?? null, removed, pluginRemoved };
}

export async function status(projectDir: string = process.cwd(), online: boolean = false): Promise<StatusReport> {
  const manifestAt = async (scope: Scope, dir: string): Promise<{ mode: "copy" | "plugin"; version: string } | null> => {
    const data: ManifestData | null = await new InstallManifest(scopeBase(scope, dir), PLUGIN_NAME).read();
    return data === null ? null : { mode: data.mode, version: data.version };
  };
  return new StatusReporter({ manifestAt }).report(projectDir, { scopes: null, online, packageName: PLUGIN_NAME });
}

export async function isInstalledAnywhere(projectDir: string = process.cwd()): Promise<boolean> {
  const version = await getPackageVersion();
  for (const scope of ["global", "local"] as const) {
    const manifest = new InstallManifest(scopeBase(scope, projectDir), PLUGIN_NAME);
    const data = await manifest.read();
    if (data === null) continue;
    if (data.mode === "plugin" && data.entryConfigPath) {
      if ((await editor.findRegistration(PLUGIN_NAME, { scope, projectDir })) !== null) return true;
      continue;
    }
    if (data.version === version) return true;
  }
  return false;
}

async function readJsonConfig(path: string): Promise<Record<string, unknown> | null> {
  if (!(await exists(path))) return {};
  try {
    return JSON.parse(await readFile(path, "utf-8")) as Record<string, unknown>;
  } catch {
    console.warn(`Warning: ${path} is not valid JSON; refusing to modify it.`);
    return null;
  }
}

async function writeJsonConfig(path: string, config: Record<string, unknown>): Promise<void> {
  await mkdir(join(path, ".."), { recursive: true });
  await writeFile(path, JSON.stringify(config, null, 2));
}

# Inputs

| Placeholder | Required | Description | Default |
|---|---|---|---|
| `EXTENSION NAME` → "myextension" | Yes | Extension identifier used in the advisory text | — |
| `SKILL NAME` → "myextension" | Yes | Must match the folder name in skills/ at the package root | — |
| `COMMAND NAME` → "my-command.md" | Yes | Command file name in commands/ at the package root | — |
| `PACKAGE NAME` → "opencode-myextension" | Yes | npm package name; must match package.json; also the stable plugin id | — |

**Load-bearing — do not simplify:** the entry is an Effect-first v2 plugin definition (`Plugin.define({ id, effect })` from `@opencode/plugin/effect`) whose `id` is the stable package name — duplicate ids die activation and storage is scoped per id (facts §2); scope detection is read-only config inspection through the `opencode-architect/core` dependency (`PluginConfigEditor.findRegistration` per scope: both `opencode.json` and `opencode.jsonc`, global and project, plus the legacy global `config.json` read-only), reading the launch directory from `context.location.directory` — never directory-identity comparisons (`import.meta.dirname`, `process.cwd()`, realpath) — a maintainer's own checkout is served by that repo's own config registration; the effect body calls only `ensureAssets` — it never resolves an install mode, never edits `plugins` arrays, permission, or any config file, and writes stay inside the detected registration scope(s) only; assets-only and code-backed packages share this body unchanged: assets are ensured in registered scopes either way, and code-backed assets resolve from the package at load; the **entire effect body** (detection, ensures, advisory) is wrapped so a failure degrades to a warning and OpenCode still launches — the effect's error channel stays `never` and it must never interrupt startup (ADR-0007); the failure advisory names both the remediation command (`bunx <package> install --scope global`) and the package-qualified cache dir (`<cacheRoot>/opencode/npm/<package>@<version>`), tells the consumer to run `bunx <package> clear-cache` for a partial cache artifact instead of describing manual removal, is built inside its own guarded effect with a static fallback, and each emitter swallows independently; the failure advisory and the not-installed advisory carry **separate** once-guards so neither suppresses the other; the zero-write no-op covers a fully matching manifest **and** a present plugin entry (an up-to-date manifest alone is not enough for plugin installs), so a healthy startup performs no writes at all; the effect never deletes the cache — it instructs only.

---
import { sep } from "node:path";
import { Effect, type Scope } from "effect";
import { Plugin } from "@opencode/plugin/effect";
import { PluginConfigEditor } from "opencode-architect/core";
import { ensureAssets, isInstalledAnywhere, packageCacheRoot } from "./installer.ts";

const PACKAGE_NAME = "opencode-myextension";
const EXTENSION_TITLE = "MyExtension";

let notInstalledAdvised = false;
let failureAdvised = false;

async function adviseNotInstalledOnce(): Promise<void> {
  if (notInstalledAdvised) return;
  notInstalledAdvised = true;
  console.log(`\nOpenCode ${EXTENSION_TITLE} is not registered in any scope.`);
  console.log(`  Install globally: bunx ${PACKAGE_NAME} install --scope global`);
  console.log(`  Install locally:  bunx ${PACKAGE_NAME} install\n`);
}

async function adviseFailureOnce(message: string): Promise<void> {
  if (failureAdvised) return;
  failureAdvised = true;
  let text: string;
  try {
    let version = "<version>";
    try {
      version = JSON.parse(await Bun.file(`${import.meta.dirname}/../package.json`).text()).version ?? version;
    } catch {}
    const cacheCopy = `${packageCacheRoot()}${sep}${PACKAGE_NAME}@${version}`;
    text = `${EXTENSION_TITLE} load-time install failed. Run: bunx ${PACKAGE_NAME} clear-cache, then: bunx ${PACKAGE_NAME} install --scope global. The stale cache copy is ${cacheCopy}. Cause: ${message}`;
  } catch {
    text = `${EXTENSION_TITLE} load-time install failed. Run: bunx ${PACKAGE_NAME} clear-cache, then: bunx ${PACKAGE_NAME} install --scope global (the stale copy lives under the OpenCode npm cache)`;
  }
  try {
    console.warn(`[${PACKAGE_NAME}] ${text}`);
  } catch {}
}

function advisoryEffect(run: () => Promise<void>): Effect.Effect<void, never, never> {
  return Effect.asVoid(
    Effect.orElseSucceed(Effect.tryPromise({ try: run, catch: () => "advisory failed" }), () => undefined),
  );
}

function ensureRegisteredScopeAssets(context: Plugin.Context): Effect.Effect<void, never, Scope.Scope> {
  return Effect.asVoid(
    Effect.catch(
      Effect.tryPromise({
        try: async () => {
          const directory = context.location.directory;
          const editor = new PluginConfigEditor();
          if ((await editor.findRegistration(PACKAGE_NAME, { scope: "global", projectDir: directory })) !== null) {
            await ensureAssets("global", directory, false);
          }
          if ((await editor.findRegistration(PACKAGE_NAME, { scope: "local", projectDir: directory })) !== null) {
            await ensureAssets("local", directory, false);
          }
          if (await isInstalledAnywhere(directory)) return;
          await adviseNotInstalledOnce();
        },
        catch: (error) => (error instanceof Error ? error.message : String(error)),
      }),
      (message) => advisoryEffect(() => adviseFailureOnce(message)),
    ),
  );
}

const plugin = Plugin.define({
  id: PACKAGE_NAME,
  effect: Effect.fn(function* (context) {
    yield* ensureRegisteredScopeAssets(context);
  }),
});

export default plugin;
